const input=$('Begin Fresh Generation').first().json;
const raw=$json.body ?? $json;
const fail=(code,message)=>[{json:{ready:false,statusCode:502,response:{text:'',error:{code,message},requestId:input.requestId}}}];
const choice=raw.choices?.[0];
if ($json.error || raw.error || !choice?.message?.content || choice.finish_reason==='length') return fail('PLANNING_FAILED','The research plan could not be generated. Please try again shortly.');
let plan;
try { plan=JSON.parse(choice.message.content.replace(/^```(?:json)?\s*|\s*```$/g,'')); } catch { return fail('INVALID_PLAN','The model returned an invalid research plan. Please try again.'); }
if (!plan || typeof plan.idea!=='string' || !plan.idea.trim()) return fail('INVALID_PLAN','The model could not identify an idea. Add a little more detail.');
const scrub=q=>String(q).replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,'').replace(/https?:\/\/\S+/g,'').replace(/\b(?:sk-|tvly-|Bearer\s+)\S+/gi,'').replace(/(?:\+?\d[\d\s().-]{7,}\d)/g,'').replace(/\s+/g,' ').trim().slice(0,200);
const queries=(input.mode==='quick'||input.sparseInput)?[]:[...new Set((Array.isArray(plan.queries)?plan.queries:[]).filter(q=>typeof q==='string').map(scrub).filter(q=>q.length>8))].slice(0,4);
const researchKey='research-quality-v10.1:'+sha256(input.text);
const sensitive=/price|pricing|cost|rate|fee|current/i.test(queries.join(' '));
const economics=plan.economics && typeof plan.economics==='object'?plan.economics:{};
const facts={};
for (const name of ['price','units','variableCost','startupBudget']) {
  const x=economics[name];
  if (!x || typeof x.value!=='number' || !Number.isFinite(x.value) || x.value<0 || x.value>1e12 || typeof x.quote!=='string' || !x.quote || !input.text.includes(x.quote)) continue;
  const values=(x.quote.replace(/,/g,'').match(/-?\d+(?:\.\d+)?/g)||[]).map(Number);
  if(values.includes(x.value)) facts[name]={value:x.value,quote:x.quote};
}
// Bind the time period to the validated quantity, not an unrelated budget.
const unitQuote=facts.units?.quote??'';
const unitAt=unitQuote?input.text.indexOf(unitQuote):-1;
const unitContext=unitAt>=0?input.text.slice(unitAt,unitAt+unitQuote.length+30).split(/[.;\n]/)[0]:'';
const timeMatch=unitContext.match(/\b(?:per|a|each|every)\s+(day|week|month|quarter|year)\b|\b(daily|weekly|monthly|quarterly|yearly|annually)\b/i);
const periodNames={daily:'day',weekly:'week',monthly:'month',quarterly:'quarter',yearly:'year',annually:'year'};
const suppliedPeriod=typeof economics.period==='string'?economics.period.trim():'';
const period=timeMatch?(timeMatch[1]?.toLowerCase()??periodNames[timeMatch[2].toLowerCase()]):suppliedPeriod&&unitContext.toLowerCase().includes(suppliedPeriod.toLowerCase())?suppliedPeriod.replace(/^(?:per|each|every|a)\s+/i,'').slice(0,40):'supplied period (verify)';
const calculations=[];
const round=n=>Math.round(n*100)/100;
if(facts.price && facts.units) calculations.push({label:'Revenue per '+period,formula:`${facts.price.value} x ${facts.units.value}`,value:round(facts.price.value*facts.units.value)});
if(facts.variableCost && facts.units) calculations.push({label:'Variable costs per '+period,formula:`${facts.variableCost.value} x ${facts.units.value}`,value:round(facts.variableCost.value*facts.units.value)});
if(facts.price && facts.variableCost) {
 const contribution=round(facts.price.value-facts.variableCost.value);
 calculations.push({label:'Contribution per unit (not profit)',formula:`${facts.price.value} - ${facts.variableCost.value}`,value:contribution});
 if(facts.units) calculations.push({label:'Contribution per '+period+' before other costs',formula:`${contribution} x ${facts.units.value}`,value:round(contribution*facts.units.value)});
 if(contribution>0 && facts.startupBudget) calculations.push({label:'Whole units to recover startup budget, excluding other costs',formula:`ceil(${facts.startupBudget.value} / ${contribution})`,value:Math.ceil(facts.startupBudget.value/contribution)});
}
const normalized=input.text.replace(/\s+/g,' ');
const details=(Array.isArray(plan.details)?plan.details:[]).filter(x=>typeof x?.detail==='string'&&typeof x.quote==='string'&&x.quote.trim().length>2&&x.quote.length<=300&&normalized.includes(x.quote.replace(/\s+/g,' ').trim())).slice(0,24).map((x,i)=>({id:'D'+(i+1),detail:x.detail.slice(0,600),quote:x.quote}));
const uncertainties=(Array.isArray(plan.uncertainties)?plan.uncertainties:[]).filter(x=>typeof x==='string').map(x=>x.slice(0,400)).slice(0,8);
const kind=['idea','conversation','recording_test','unclear'].includes(plan.kind)?plan.kind:'idea';
const language=typeof plan.language==='string'?plan.language.slice(0,12):'en';
return [{json:{...input,ready:true,details,uncertainties,kind,language,idea:plan.idea.slice(0,1000),assumptions:(Array.isArray(plan.assumptions)?plan.assumptions:[]).filter(x=>typeof x==='string').slice(0,4),queries,researchKey,researchTtlMs:sensitive?21600000:86400000,facts,calculations,plannerUsage:raw.usage??{},plannerProvider:raw.provider??null}}];

const input=$('Validate Source Details').first().json;
let research;
try {if(Number($json.expiresAt)>Date.now()) research=JSON.parse($json.payload);}catch{}
if(input.queries.length===0) return [{json:{...input,needsSearch:false,research:{sources:[],status:'skipped',queries:[],searchedAt:null,searchCalls:0,cache:'not_accessed'}}}];
