const context=$('Validate Source Details').first().json;
const replies=$input.all();
const groups=[]; const seen=new Set(); let failures=0;
const clean=s=>String(s??'').replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/\s+/g,' ').trim();
for(const item of replies) {
 const sources=[]; groups.push(sources);
 const r=item.json.body??item.json;
 if(item.json.error || r.error || (item.json.statusCode && item.json.statusCode!==200)) {failures++;continue;}
 for(const result of (r.web?.results??[]).slice(0,8)) {
  let url;
  const match=String(result.url??'').match(/^https?:\/\/([a-z0-9.-]+)(?::\d+)?(?:[/?][^\s<>]*)?$/i);
  if(!match||match[1]==='localhost'||/^(?:127\.|10\.|192\.168\.|169\.254\.|172\.(?:1[6-9]|2\d|3[01])\.)/.test(match[1]))continue;
  url=String(result.url).split('#')[0].replace(/^https:\/\/arxiv\.org\/pdf\//,'https://arxiv.org/abs/');
  if(/^https:\/\/(?:www\.)?edisonresearch\.com\/the-infinite-dial-2026\/?$/.test(url))url='https://ssrs.com/insights/the-infinite-dial-2026/';
  if(seen.has(url))continue;seen.add(url);
  const excerpts=[result.description,...(Array.isArray(result.extra_snippets)?result.extra_snippets:[])].map(clean).filter(Boolean);
  const excerpt=[...new Set(excerpts)].join(' ').slice(0,1600);
  if(!excerpt)continue;
  const dated=publicationEvidence('',result.page_age);if(dated.recency==='outside_window')continue;
  sources.push({id:'',queryIndex:groups.length-1,title:clean(result.title).slice(0,160),url,excerpt,publishedDate:result.page_age??null});
 }
}
// Preserve the strongest ranked results from both queries, rather than filling the budget from only the first.
const selected=[];
for(let rank=0;rank<8&&selected.length<32;rank++)for(const group of groups)if(group[rank]&&selected.length<32)selected.push(group[rank]);
const stop=new Set('about after again could doing first great have idea into just like more only other platform product should their there these they this those want what when which while with would your'.split(' '));
const terms=[...new Set(context.text.toLowerCase().match(/[a-z]{4,}/g)||[])].filter(x=>!stop.has(x));
const score=s=>{const t=(s.title+' '+s.excerpt).toLowerCase();return terms.filter(x=>t.includes(x)).length-(/reddit.com|quora.com|pinterest.com/i.test(s.url)?4:0)-(/best.*tools|top.*tools|voice generator|text.to.speech|prompt to audio/i.test(s.title)?4:0);};
